function blank(value) {
  return String(value ?? "").trim();
}

function touchKey(personId, postId, kind, reaction) {
  const reactionPart = kind === "comment" ? "" : blank(reaction);
  return [personId, postId, kind, reactionPart].join("|");
}

function rollUpEngagers(input = {}) {
  const posts = Array.isArray(input.posts) ? input.posts : [];
  const keptPosts = new Map();
  for (const post of posts) {
    const id = blank(post.id);
    if (!id || post.is_repost) continue;
    keptPosts.set(id, post);
  }
  const excluded = new Set((input.exclude_person_ids ?? []).map((id) => blank(id)).filter(Boolean));
  const touches = new Map();

  for (const row of input.engagements ?? []) {
    const postId = blank(row.post_id);
    const personId = blank(row.person_id);
    if (!personId || !keptPosts.has(postId) || excluded.has(personId)) continue;
    const kind = row.kind === "comment" ? "comment" : "reaction";
    const reaction = kind === "comment" ? "" : blank(row.reaction);
    const key = touchKey(personId, postId, kind, reaction);
    const at = blank(row.at);
    const existing = touches.get(key);
    if (!existing) {
      touches.set(key, {
        key,
        person_id: personId,
        post_id: postId,
        kind,
        reaction,
        at,
        name: blank(row.name),
      });
      continue;
    }
    if (at && (!existing.at || at < existing.at)) existing.at = at;
    const name = blank(row.name);
    if (name.length > existing.name.length) existing.name = name;
  }

  const byPerson = new Map();
  for (const touch of touches.values()) {
    let person = byPerson.get(touch.person_id);
    if (!person) {
      person = {
        person_id: touch.person_id,
        name: touch.name,
        first_seen: touch.at,
        last_seen: touch.at,
        last_post_id: touch.post_id,
        touches: 0,
        posts: new Set(),
        comment_count: 0,
        best_evidence: "reaction",
      };
      byPerson.set(touch.person_id, person);
    }
    person.touches += 1;
    person.posts.add(touch.post_id);
    if (touch.kind === "comment") {
      person.comment_count += 1;
      person.best_evidence = "comment";
    }
    if (touch.name.length > person.name.length) person.name = touch.name;
    if (touch.at && (!person.first_seen || touch.at < person.first_seen)) person.first_seen = touch.at;
    if (touch.at && (!person.last_seen || touch.at > person.last_seen || (touch.at === person.last_seen && touch.post_id > person.last_post_id))) {
      person.last_seen = touch.at;
      person.last_post_id = touch.post_id;
    }
  }

  const people = [...byPerson.values()]
    .map((person) => ({
      person_id: person.person_id,
      name: person.name,
      first_seen: person.first_seen,
      last_seen: person.last_seen,
      touches: person.touches,
      distinct_posts: person.posts.size,
      comment_count: person.comment_count,
      last_post_id: person.last_post_id,
      best_evidence: person.best_evidence,
    }))
    .sort((a, b) => a.person_id.localeCompare(b.person_id));

  const touchRows = [...touches.values()]
    .map(({ name, ...touch }) => touch)
    .sort((a, b) => a.key.localeCompare(b.key));

  return { touches: touchRows, people };
}

const DAY = 86400000;

function ageDays(asOf, seen) {
  const end = Date.parse(asOf);
  const start = Date.parse(seen);
  if (Number.isNaN(end) || Number.isNaN(start)) return null;
  return (end - start) / DAY;
}

function baseTier(person, rules) {
  if (person.in_team) return { tier: "hold", reason: "person is on the team list" };
  if (person.fit === null || person.fit === undefined || person.fit === "") {
    return { tier: "hold", reason: "fit is unknown" };
  }
  const fit = Number(person.fit);
  const commented = Number(person.comment_count || 0) > 0;
  const repeated = Number(person.distinct_posts || 0) >= 2;
  if (fit >= rules.top_fit && (commented || repeated)) {
    return { tier: "1", reason: "fit is at the top line and they engaged more than once or left a comment" };
  }
  if (fit >= rules.middle_fit) {
    return { tier: "2", reason: "fit is at the middle line" };
  }
  return { tier: "3", reason: "fit is under the middle line" };
}

function dropOne(tier) {
  if (tier === "1") return "2";
  if (tier === "2") return "3";
  return tier;
}

function tierEngagers(input = {}) {
  const rules = {
    top_fit: 75,
    middle_fit: 55,
    recency_days: 30,
    tier_1_cap_per_week: 10,
    ...input.rules,
  };
  const team = new Set((input.exclude_person_ids ?? []).map((id) => String(id)));
  const rows = (input.people ?? []).map((person) => {
    const inTeam = Boolean(person.in_team) || team.has(person.person_id);
    const decided = baseTier({ ...person, in_team: inTeam }, rules);
    let tier = decided.tier;
    let reason = decided.reason;
    const age = ageDays(input.as_of, person.last_seen);
    if (tier !== "hold" && age !== null && age > rules.recency_days) {
      const next = dropOne(tier);
      if (next !== tier) {
        reason = `${reason}. Last touch is outside ${rules.recency_days} days, so the tier drops from ${tier} to ${next}`;
        tier = next;
      } else {
        reason = `${reason}. Last touch is outside ${rules.recency_days} days and this is already the lowest tier`;
      }
    }
    return {
      person_id: person.person_id,
      fit: person.fit ?? null,
      tier,
      reason,
      last_seen: person.last_seen ?? null,
    };
  });

  const tierOne = rows
    .filter((row) => row.tier === "1")
    .sort((a, b) => {
      const fitDelta = Number(b.fit) - Number(a.fit);
      if (fitDelta !== 0) return fitDelta;
      const seen = String(b.last_seen).localeCompare(String(a.last_seen));
      if (seen !== 0) return seen;
      return a.person_id.localeCompare(b.person_id);
    });
  const overflow = new Set(tierOne.slice(rules.tier_1_cap_per_week).map((row) => row.person_id));
  for (const row of rows) {
    if (!overflow.has(row.person_id)) continue;
    row.reason = `${row.reason}. Over the weekly cap of ${rules.tier_1_cap_per_week}, so this row moves to tier 2`;
    row.tier = "2";
  }
  rows.sort((a, b) => a.person_id.localeCompare(b.person_id));
  return { rows, rules };
}
